/// <summary>
/// The <c>AVAWHSControlCoilWeight</c> class is responsible for handling the coil weight
/// </summary>
#AVAWHSRF
[
    WhsControlFactory(#AVACoilWeight)
]
public class AVAWHSControlCoilWeight extends WhsControl
{
}

Method.Source:
public boolean process()
{
    Weight                  avaLocationWeight;
    AVACoilMaterialWeight   avaCoilMaterialWeight = WHSWorkExecuteDisplay::str2numDisplay(data);

    if (this.parmData())
    {
        avaLocationWeight = this.avaGetLocationWeight();

        if (avaCoilMaterialWeight != 0)
        {
            if (avaCoilMaterialWeight < 0)
            {
                if (abs(avaCoilMaterialWeight) >  avaLocationWeight)
                {
                    return this.fail("@NDX:WrongAdjustQty");
                }
            }

            fieldValues.insert(#AVACoilWeight, this.parmData());
        }
    }

    return super();
}

protected InventQtyPhysicalOnhand avaQtyOnLocation()
{
    InventDim avaInventDimCriteria;

    avaInventDimCriteria = pass.createInventDimFromPass();

    avaInventDimCriteria.clearBelowLocationDim(pass.parmItemId());
    avaInventDimCriteria = InventDim::findOrCreate(avaInventDimCriteria);
    avaInventDimCriteria.LicensePlateId = pass.parmLicensePlateId();

    return AVACoilCalculator::qtyOnLocation(pass.parmItemId(), avaInventDimCriteria);
}
